  g.fillStyle = '#2f6fb2';
  g.fillRect(3060 * s, 0, (WORLD_SIZE - 3060) * s, 1600);
  g.fillStyle = '#e8d9a0';
  g.fillRect(2980 * s, 0, 80 * s, 1600);
  // Roads.
  g.fillStyle = '#3a3a40';
