  } else if (st.type === 'checkpoints') {
    const pt = st.points[st.idx];
    if (pt && dist(p.x, p.y, pt.x, pt.y) < 90) {
      st.idx++;
      sfx('pickup');
      if (st.idx >= st.points.length) advanceStage();
