  g.fillStyle = p.hp > 50 ? '#3ac95a' : p.hp > 25 ? '#e8a832' : '#d83a3a';
  g.fillRect(18, 62, 216 * Math.max(0, p.hp / 100), 18);
  g.fillStyle = '#fff';
  g.font = 'bold 14px sans-serif';
