  const tw = g.measureText(label).width;
  g.fillRect(viewW / 2 - tw / 2 - 14, 10, tw + 28 + 70, 30);
  g.fillStyle = '#ffd23a';
  g.fillText(label, viewW / 2 - tw / 2, 32);
  const bars = radioEqBars();
  bars.forEach((b, i) => {
    const h = 6 + b * 16;
