  // Objective banner, lower-left, bold over a dark scrim.
  const st = stage();
  const objective = S.mission
    ? `${S.mission.name}: ${st ? st.label : ''}${S.missionTimeLeft > 0 ? `  (${Math.ceil(S.missionTimeLeft)}s)` : ''}`
